from collections import deque

class Graph:
    def __init__(self):
        self.graph = {}

    def add_node(self, node):
        if node not in self.graph:
            self.graph[node] = []

    def add_edge(self, node1, node2):
        self.graph[node1].append(node2)

    def bfs(self, start_node):
        visited = set()
        queue = deque([start_node])
        visited.add(start_node)

        while queue:
            curr_node = queue.popleft()
            print(curr_node, end=" ") 

            for neighbor in self.graph[curr_node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        return

    def astar(self, start_node, goal_node):
        # Initialize data structures
        open_set = deque()  # Store nodes to be explored
        closed_set = set()  # Store already visited nodes

        # Define heuristic function (e.g., Manhattan distance)
        def heuristic(node1, node2):
            return abs(node1[0] - node2[0]) + abs(node1[1] - node2[1])

        g_values = {node: float('inf') for node in self.graph}
        g_values[start_node] = 0  # Initialize starting node's cost to 0
        h_values = {node: float('inf') for node in self.graph}
        h_values[start_node] = heuristic(start_node, goal_node)

        open_set.append((g_values[start_node], start_node, None))  # (cost, node, parent)

        while open_set:
            current_cost, current_node, parent = open_set.popleft() # Get node with the lowest cost

            if current_node == goal_node:
                return reconstruct_path(parent, goal_node)

            closed_set.add(current_node)

            for neighbor in self.graph[current_node]:
                tentative_g_value = current_cost + 1  # Cost to reach the neighbor
                if neighbor in closed_set or neighbor not in self.graph:
                    continue

                if tentative_g_value < g_values[neighbor]:
                    g_values[neighbor] = tentative_g_value
                    h_values[neighbor] = heuristic(neighbor, goal_node)
                    open_set.append((tentative_g_value, neighbor, current_node))

        return "No Path Found"  # Goal not reachable


def reconstruct_path(parent, goal_node):
    path = []
    current_node = goal_node
    while current_node:
        path.append(current_node)
        current_node = parent[current_node]
    path.reverse()
    return path


